package main

import (
	"bufio"
	"fmt"
	"os"
)

type DataReader struct {
	scanner *bufio.Scanner
}

func NewDataReader(r *os.File) *DataReader {
	scanner := bufio.NewScanner(r)
	scanner.Split(bufio.ScanWords)
	return &DataReader{scanner: scanner}
}

func (dr *DataReader) next() string {
	if dr.scanner.Scan() {
		return dr.scanner.Text()
	}
	return ""
}

func (dr *DataReader) nextToken() string {
	return dr.next()
}

func (dr *DataReader) nextInt() int {
	var x int
	fmt.Sscan(dr.nextToken(), &x)
	return x
}

func (dr *DataReader) nextLong() int64 {
	var x int64
	fmt.Sscan(dr.nextToken(), &x)
	return x
}

func (dr *DataReader) readIntArray(n int) []int {
	result := make([]int, n)
	for i := range result {
		result[i] = dr.nextInt()
	}
	return result
}

func (dr *DataReader) nextLine() string {
	if dr.scanner.Scan() {
		return dr.scanner.Text()
	}
	return ""
}

func toYesNo(b bool) string {
	if b {
		return "YES"
	}
	return "NO"
}

func solve(dr *DataReader, out *bufio.Writer) {
	n := dr.nextInt()
	k := dr.nextInt()
	s := dr.nextToken()

	used := make([]bool, n)

	var dfs func(int) bool
	dfs = func(u int) bool {
		if u < 0 || u >= n || used[u] || s[u] == '#' {
			return false
		}
		if s[u] == 'T' {
			return true
		}
		used[u] = true
		return dfs(u-k) || dfs(u+k)
	}

	start := -1
	for i := 0; i < n; i++ {
		if s[i] == 'G' {
			start = i
			break
		}
	}

	fmt.Fprintln(out, toYesNo(dfs(start)))
}

