		fout, _ := os.Create("output.txt")
		out = bufio.NewWriter(fout)
	} else {
		r = os.Stdin
		out = bufio.NewWriter(os.Stdout)
	}

	dr := NewDataReader(r)
	solve(dr, out)
	out.Flush()
}

